import json, glob

# Check v8: how many trajectories succeeded vs failed, and look at step counts
for ver in ['v7', 'v8']:
    success = 0; fail = 0; total_steps = []
    for pattern in [f'/root/autodl-tmp/rl-active-probe-fl/data/trajectories_{ver}_icl_cuda0/*.jsonl',
                    f'/root/autodl-tmp/rl-active-probe-fl/data/trajectories_{ver}_icl_cuda1/*.jsonl']:
        for fp in glob.glob(pattern):
            with open(fp) as f:
                for line in f:
                    t = json.loads(line)
                    if t.get('reward'):
                        success += 1
                    else:
                        fail += 1
                    total_steps.append(t.get('steps',0))
    if total_steps:
        print(f'{ver}: success={success}, fail={fail}, avg_steps={sum(total_steps)/len(total_steps):.1f}, max_steps={max(total_steps)}')
    else:
        print(f'{ver}: no data')
"
